42	func parseRuntimeOptions() runtimeOptions {
43		var (
44			configPath             = flag.String("config", "config/config.yaml", "Path to the configuration file")
45			port                   = flag.Int("port", 50051, "Port to listen on for gRPC ExtProc")
46			apiPort                = flag.Int("api-port", 8080, "Port to listen on for the router apiserver")
47			apiBind                = flag.String("api-bind", "", "Bind address for the router apiserver (default from config: 127.0.0.1)")
48			managementAuthMode     = flag.String("management-auth-mode", "", "Management API auth mode: bearer or disabled")
49			managementRemoteExpose = flag.Bool("management-remote-exposure", false, "Allow remote exposure of the management API (requires bearer auth tokens in config)")
50			metricsPort            = flag.Int("metrics-port", 9190, "Port for Prometheus metrics")
51			enableAPI              = flag.Bool("enable-api", true, "Enable the router apiserver")
52			secure                 = flag.Bool("secure", false, "Enable secure gRPC server with TLS")
53			certPath               = flag.String("cert-path", "", "Path to TLS certificate directory (containing tls.crt and tls.key)")
54			kubeconfig             = flag.String("kubeconfig", "", "Path to kubeconfig file (optional, uses in-cluster config if not specified)")
55			namespace              = flag.String("namespace", "default", "Kubernetes namespace to watch for CRDs")
56			downloadOnly           = flag.Bool("download-only", false, "Download required models and exit (useful for CI/testing)")
57		)
58		flag.Parse()
59	
60		return runtimeOptions{
61			configPath:             *configPath,
62			certPath:               *certPath,
63			kubeconfig:             *kubeconfig,
64			namespace:              *namespace,
65			port:                   *port,
66			apiPort:                *apiPort,
67			apiBind:                *apiBind,
68			managementAuthMode:     *managementAuthMode,
69			managementRemoteExpose: boolFlagOverride(flag.CommandLine, "management-remote-exposure", *managementRemoteExpose),
70			metricsPort:            *metricsPort,
71			enableAPI:              *enableAPI,
72			secure:                 *secure,
73			downloadOnly:           *downloadOnly,
74		}
75	}
76	
77	// boolFlagOverride returns a pointer to value only when the named flag was
78	// explicitly supplied on the command line. Otherwise nil so config defaults
79	// are preserved (e.g. management_api.remote_exposure: true).
80	func boolFlagOverride(fs *flag.FlagSet, name string, value bool) *bool {
81		set := false
82		fs.Visit(func(f *flag.Flag) {
83			if f.Name == name {
84				set = true
85			}
86		})
87		if !set {
88			return nil
89		}
90		return &value
91	}
