99	func loadRuntimeConfigOrFatal(configPath string) *config.RouterConfig {
100		if _, err := os.Stat(configPath); os.IsNotExist(err) {
101			logging.ComponentFatalEvent("router", "runtime_config_missing", map[string]interface{}{
102				"config_path": configPath,
103			})
104		}
105	
106		cfg, err := config.Parse(configPath)
107		if err != nil {
108			logging.ComponentFatalEvent("router", "runtime_config_load_failed", map[string]interface{}{
109				"config_path": configPath,
110				"error":       err.Error(),
111			})
112		}
113		logging.ComponentDebugEvent("router", "runtime_config_loaded", map[string]interface{}{
114			"config_path":    configPath,
115			"config_source":  cfg.ConfigSource,
116			"decision_count": len(cfg.Decisions),
117		})
118		return cfg
119	}
