131	func buildStartupWriter(cfg *config.RouterConfig, configPath string) startupstatus.StatusWriter {
132		if cfg.StartupStatus.StoreBackend == "redis" && cfg.StartupStatus.Redis != nil {
133			rw, err := startupstatus.NewRedisWriter(startupstatus.RedisWriterConfig{
134				Address:  cfg.StartupStatus.Redis.Address,
135				Password: cfg.StartupStatus.Redis.Password,
136				DB:       cfg.StartupStatus.Redis.DB,
137			})
138			if err != nil {
139				logging.ComponentWarnEvent("router", "startup_status_redis_fallback", map[string]interface{}{
140					"error":    err.Error(),
141					"fallback": "file",
142				})
143				return startupstatus.NewFileWriter(configPath)
144			}
145			logging.ComponentEvent("router", "startup_status_backend", map[string]interface{}{
146				"backend": "redis",
147				"address": cfg.StartupStatus.Redis.Address,
148			})
149			return rw
150		}
151	
152		logging.ComponentWarnEvent("router", "startup_status_file_backend", map[string]interface{}{
153			"backend": "file",
154			"message": "Startup status using local file backend. Status is not shared across replicas or visible to the dashboard in containerized deployments. Set startup_status.store_backend: redis for production use.",
155		})
156		return startupstatus.NewFileWriter(configPath)
157	}
