159	func writeStartupState(writer startupstatus.StatusWriter, state startupstatus.State, warning string) {
160		if err := writer.Write(state); err != nil {
161			logging.ComponentWarnEvent("router", "startup_state_write_failed", map[string]interface{}{
162				"warning": warning,
163				"phase":   state.Phase,
164				"ready":   state.Ready,
165				"error":   err.Error(),
166			})
167		}
168	}
