170	func failStartup(writer startupstatus.StatusWriter, format string, args ...interface{}) {
171		message := fmt.Sprintf(format, args...)
172		_ = writer.Write(startupstatus.State{
173			Phase:   "error",
174			Ready:   false,
175			Message: message,
176		})
177		logging.ComponentFatalEvent("router", "startup_failed", map[string]interface{}{
178			"message": message,
179		})
180	}
