439	func warmupRouterRuntime(server *extproc.Server, embeddingState modelruntime.EmbeddingRuntimeState) {
440		router := server.GetRouter()
441		if router == nil {
442			return
443		}
444		_, _ = modelruntime.WarmupRouter(context.Background(), []modelruntime.RouterWarmupTask{
445			{
446				Name:       "tools_database",
447				Ready:      embeddingState.ToolsReady,
448				SkipReason: "embedding_runtime_not_ready_for_tools",
449				Load:       router.LoadToolsDatabase,
450			},
451			{
452				Name:       "knowledge_bases",
453				Ready:      embeddingState.AnyReady,
454				SkipReason: "embedding_runtime_not_ready_for_knowledge_bases",
455				Load:       router.PreloadKnowledgeBases,
456			},
457		}, modelruntime.WarmupRouterOptions{
458			Component:      "router",
459			MaxParallelism: 2,
460			OnEvent:        logRuntimeLifecycleEvent,
461		})
462	}
