11	
12	func (r *OpenAIRouter) handleDirectFlowExecution(
13		openAIRequest *openai.ChatCompletionNewParams,
14		originalModel string,
15		ctx *RequestContext,
16	) (*ext_proc.ProcessingResponse, error) {
17		if r.Config == nil || !r.Config.Looper.IsEnabled() {
18			return r.createErrorResponse(500, "Flow execution requires global.integrations.looper.endpoint"), nil
19		}
20	
21		ctx.RequestModel = originalModel
22		decision, status, err := r.resolveDirectFlowDecision(ctx)
23		if err != nil {
24			return r.createErrorResponse(status, err.Error()), nil
25		}
26		ctx.VSRSelectedDecision = decision
27		ctx.VSRSelectedDecisionName = decision.Name
28		ctx.VSRSelectionMethod = "workflows"
29	
30		return r.handleLooperExecution(ctx.TraceContext, openAIRequest, decision, ctx)
31	}
32	
33	func (r *OpenAIRouter) resolveDirectFlowDecision(ctx *RequestContext) (*config.Decision, int, error) {
34		if isFlowDecision(ctx.VSRSelectedDecision) {
35			return ctx.VSRSelectedDecision, 0, nil
36		}
37		if ctx.VSRSelectedDecision != nil {
38			return nil, 400, fmt.Errorf("no eligible Flow decision matched for model %q", ctx.RequestModel)
39		}
40		if decision := r.defaultLooperDecisionByAlgorithm("workflows"); decision != nil {
41			return decision, 0, nil
42		}
43		return nil, 400, fmt.Errorf("no eligible Flow decision matched for model %q", ctx.RequestModel)
44	}
45	
46	func isFlowDecision(decision *config.Decision) bool {
47		return decision != nil && decision.Algorithm != nil && decision.Algorithm.Type == "workflows"
48	}
