71	// SignalMatches contains all matched signals for decision evaluation
72	type SignalMatches struct {
73		KeywordRules      []string
74		EmbeddingRules    []string
75		DomainRules       []string
76		FactCheckRules    []string // "needs_fact_check" or "no_fact_check_needed"
77		UserFeedbackRules []string // "need_clarification", "satisfied", "want_different", "wrong_answer"
78		ReaskRules        []string // History-aware dissatisfaction signals from repeated user turns
79		PreferenceRules   []string // Route preference names matched via external LLM
80		LanguageRules     []string // Language codes: "en", "es", "zh", "fr", etc.
81		ContextRules      []string // Context rule names matched (e.g. "low_token_count")
82		StructureRules    []string // Structure rule names matched (e.g. "many_questions")
83		ComplexityRules   []string // Complexity rules with difficulty level (e.g. "code_complexity:hard")
84		ModalityRules     []string // Modality classification: "AR", "DIFFUSION", or "BOTH"
85		AuthzRules        []string // Authz rule names matched for user-level routing (e.g. "premium_tier")
86		JailbreakRules    []string // Jailbreak rule names matched (confidence >= threshold)
87		PIIRules          []string // PII rule names matched (denied PII types detected)
88		KBRules           []string // KB signal names matched from global.model_catalog.kbs bindings
89		ConversationRules []string // Conversation-shape signal names matched
90		EventRules        []string // event rule names (event type, severity, temporal, action codes)
91		MetadataRules     []string // untrusted request metadata rule names matched
92		ClassifierRules   []string // generic classifier label names matched
93		ProjectionRules   []string // Derived routing outputs from routing.projections.mappings
94	
95		SignalConfidences map[string]float64 // "signalType:ruleName" → real score (0.0-1.0), e.g. {"embedding:ai": 0.88}. Defaults to 1.0 if missing
96		SignalValues      map[string]float64 // raw numeric values exposed by signal evaluators
97		SignalErrors      map[string]string  // signal evaluation errors keyed by "type:name"
98	}
