108	// EvaluateDecisions evaluates all decisions and returns the best match based on strategy
109	// matchedKeywordRules: list of matched keyword rule names
110	// matchedEmbeddingRules: list of matched embedding rule names
111	// matchedDomainRules: list of matched domain rule names (category names)
112	func (e *DecisionEngine) EvaluateDecisions(
113		matchedKeywordRules []string,
114		matchedEmbeddingRules []string,
115		matchedDomainRules []string,
116	) (*DecisionResult, error) {
117		// Call EvaluateDecisionsWithSignals with empty fact_check rules for backward compatibility
118		return e.EvaluateDecisionsWithSignals(&SignalMatches{
119			KeywordRules:   matchedKeywordRules,
120			EmbeddingRules: matchedEmbeddingRules,
121			DomainRules:    matchedDomainRules,
122			FactCheckRules: nil,
123		})
124	}
125	
126	// EvaluateDecisionsWithSignals evaluates all decisions using SignalMatches
127	// This is the new method that supports all signal types including fact_check
128	func (e *DecisionEngine) EvaluateDecisionsWithSignals(signals *SignalMatches) (*DecisionResult, error) {
129		// Record decision evaluation start time
130		start := time.Now()
131		defer func() {
132			latencySeconds := time.Since(start).Seconds()
133			metrics.RecordDecisionEvaluation(latencySeconds)
134		}()
135	
136		if len(e.decisions) == 0 {
137			return nil, fmt.Errorf("no decisions configured")
138		}
139	
140		var results []DecisionResult
141	
142		// Evaluate each decision
143		for i := range e.decisions {
144			decision := &e.decisions[i]
145			matched, confidence, matchedRules := e.evaluateDecisionWithSignals(decision, signals)
146	
147			if matched {
148				// Record decision match with confidence
149				metrics.RecordDecisionMatch(config.RoutingDecisionKey(e.routingScope, decision.Name), confidence)
150	
151				results = append(results, DecisionResult{
152					Decision:     decision,
153					Confidence:   confidence,
154					MatchedRules: matchedRules,
155				})
156			}
157		}
158	
159		if len(results) == 0 {
160			logging.Infof("No decision matched")
161			return nil, nil
162		}
163	
164		// Select best decision based on strategy
165		return e.selectBestDecision(results), nil
166	}
167	
168	// evaluateDecisionWithSignals evaluates a single decision's rule tree with all signals.
169	func (e *DecisionEngine) evaluateDecisionWithSignals(
170		decision *config.Decision,
171		signals *SignalMatches,
172	) (matched bool, confidence float64, matchedRules []string) {
173		// Omitting rules is the YAML equivalent of a DSL route without WHEN. Keep
174		// this root-only contract explicit instead of relying on the zero value to
175		// fall through to OR semantics.
176		if decision.Rules.IsEmpty() {
177			return true, 0, nil
178		}
179		return e.evalNode(decision.Rules, signals)
180	}
181	
182	// evalNode recursively evaluates a RuleNode (boolean expression tree) against signal matches.
183	// Leaf nodes check whether a specific named signal is present.
184	// Composite nodes apply AND / OR / NOT logic over their children.
185	func (e *DecisionEngine) evalNode(
186		node config.RuleNode,
187		signals *SignalMatches,
188	) (matched bool, confidence float64, matchedRules []string) {
189		if node.IsLeaf() {
190			return e.evalLeaf(node, signals)
191		}
192	
193		switch strings.ToUpper(node.Operator) {
194		case "AND":
195			return e.evalAND(node.Conditions, signals)
196		case "NOT":
197			return e.evalNOT(node.Conditions, signals)
198		default: // OR
199			return e.evalOR(node.Conditions, signals)
200		}
201	}
202	
203	// evalLeaf evaluates a single signal condition (leaf node).
204	func (e *DecisionEngine) evalLeaf(
205		node config.RuleNode,
206		signals *SignalMatches,
207	) (matched bool, confidence float64, matchedRules []string) {
208		normalizedType := strings.ToLower(strings.TrimSpace(node.Type))
209	
210		matched, supported := e.matchesSignalType(normalizedType, node.Name, signals)
211		if !supported {
212			return false, 0, nil
213		}
214		if node.Predicate != nil {
215			return evaluatePredicateLeaf(node, normalizedType, signals)
216		}
217		if !matched {
218			return false, 0, nil
219		}
220	
221		confidence = signalConfidence(signals.SignalConfidences, normalizedType, node.Name)
222		return true, confidence, []string{formatMatchedRule(node)}
223	}
224	
225	func evaluatePredicateLeaf(
226		node config.RuleNode,
227		normalizedType string,
228		signals *SignalMatches,
229	) (bool, float64, []string) {
230		value, available := signalPredicateValue(signals, normalizedType, node.Name, node.Label)
231		if available {
232			if numericPredicateMatches(value, node.Predicate) {
233				return true, 1.0, []string{formatMatchedRule(node)}
234			}
235			return false, 0, nil
236		}
237		errorKey := fmt.Sprintf("%s:%s", normalizedType, node.Name)
238		_, failed := signals.SignalErrors[errorKey]
239		if failed && strings.EqualFold(strings.TrimSpace(node.OnError), "match") {
240			return true, 1.0, []string{formatMatchedRule(node)}
241		}
242		return false, 0, nil
243	}
244	
245	func formatMatchedRule(node config.RuleNode) string {
246		rule := fmt.Sprintf("%s:%s", node.Type, node.Name)
247		if node.Label != "" {
248			rule += ":" + node.Label
249		}
250		return rule
251	}
252	
253	func signalPredicateValue(
254		signals *SignalMatches,
255		signalType string,
256		name string,
257		label string,
258	) (float64, bool) {
259		key := fmt.Sprintf("%s:%s", signalType, name)
260		if label != "" {
261			key += ":" + label
262		}
263		if signals.SignalValues != nil {
264			if value, ok := signals.SignalValues[key]; ok {
265				return value, true
266			}
267		}
268		if signals.SignalConfidences != nil {
269			value, ok := signals.SignalConfidences[key]
270			return value, ok
271		}
272		return 0, false
273	}
274	
275	func numericPredicateMatches(value float64, predicate *config.NumericPredicate) bool {
276		if predicate == nil {
277			return true
278		}
279		if math.IsNaN(value) || math.IsInf(value, 0) {
280			return false
281		}
282		if predicate.GT != nil && value <= *predicate.GT {
283			return false
284		}
285		if predicate.GTE != nil && value < *predicate.GTE {
286			return false
287		}
288		if predicate.LT != nil && value >= *predicate.LT {
289			return false
290		}
291		if predicate.LTE != nil && value > *predicate.LTE {
292			return false
293		}
294		return true
295	}
296	
297	func (e *DecisionEngine) matchesSignalType(
298		normalizedType string,
299		name string,
300		signals *SignalMatches,
301	) (matched bool, supported bool) {
302		if normalizedType == "domain" {
303			return e.matchesDomainCondition(name, signals.DomainRules), true
304		}
305		if normalizedType == config.SignalTypeClassifier {
306			// Classifier conditions are predicate-only and configuration validation
307			// guarantees that the named classifier exists.
308			return false, true
309		}
310	
311		rules, ok := resolveSignalRules(normalizedType, signals)
312		if !ok {
313			return false, false
314		}
315		return slices.Contains(rules, name), true
316	}
317	
318	func resolveSignalRules(
319		signalType string,
320		signals *SignalMatches,
321	) ([]string, bool) {
322		if rules, ok := resolvePrimarySignalRules(signalType, signals); ok {
323			return rules, true
324		}
325		return resolvePolicySignalRules(signalType, signals)
326	}
327	
328	func resolvePrimarySignalRules(
329		signalType string,
330		signals *SignalMatches,
331	) ([]string, bool) {
332		switch signalType {
333		case config.SignalTypeKeyword:
334			return signals.KeywordRules, true
335		case config.SignalTypeEmbedding:
336			return signals.EmbeddingRules, true
337		case config.SignalTypeFactCheck:
338			return signals.FactCheckRules, true
339		case config.SignalTypeUserFeedback:
340			return signals.UserFeedbackRules, true
341		case config.SignalTypeReask:
342			return signals.ReaskRules, true
343		case config.SignalTypePreference:
344			return signals.PreferenceRules, true
345		case config.SignalTypeLanguage:
346			return signals.LanguageRules, true
347		case config.SignalTypeContext:
348			return signals.ContextRules, true
349		case config.SignalTypeStructure:
350			return signals.StructureRules, true
351		case config.SignalTypeComplexity:
352			return signals.ComplexityRules, true
353		default:
354			return nil, false
355		}
356	}
357	
358	func resolvePolicySignalRules(
359		signalType string,
360		signals *SignalMatches,
361	) ([]string, bool) {
362		switch signalType {
363		case config.SignalTypeModality:
364			return signals.ModalityRules, true
365		case config.SignalTypeAuthz:
366			return signals.AuthzRules, true
367		case config.SignalTypeJailbreak:
368			return signals.JailbreakRules, true
369		case config.SignalTypePII:
370			return signals.PIIRules, true
371		case config.SignalTypeKB:
372			return signals.KBRules, true
373		case config.SignalTypeConversation:
374			return signals.ConversationRules, true
375		case config.SignalTypeEvent:
376			return signals.EventRules, true
377		case config.SignalTypeMetadata:
378			return signals.MetadataRules, true
379		case config.SignalTypeProjection:
380			return signals.ProjectionRules, true
381		default:
382			return nil, false
383		}
384	}
385	
386	func signalConfidence(confidences map[string]float64, signalType string, name string) float64 {
387		if confidences == nil {
388			return 1.0
389		}
390	
391		signalKey := fmt.Sprintf("%s:%s", signalType, name)
392		if score, ok := confidences[signalKey]; ok {
393			return score
394		}
395		return 1.0
396	}
397	
398	// evalAND returns true only when every child matches.
399	// An empty conjunction acts as a catch-all/default route with zero confidence,
400	// so it can serve as a fallback without outranking signal-backed decisions when
401	// confidence-based selection is enabled.
402	func (e *DecisionEngine) evalAND(
403		children []config.RuleNode,
404		signals *SignalMatches,
405	) (matched bool, confidence float64, matchedRules []string) {
406		if len(children) == 0 {
407			return true, 0, nil
408		}
409		totalConf := 0.0
410		for _, child := range children {
411			m, c, r := e.evalNode(child, signals)
412			if !m {
413				return false, 0, nil
414			}
415			totalConf += c
416			matchedRules = append(matchedRules, r...)
417		}
418		return true, totalConf / float64(len(children)), matchedRules
419	}
420	
421	// evalOR returns true when at least one child matches; returns the best-confidence match.
422	func (e *DecisionEngine) evalOR(
423		children []config.RuleNode,
424		signals *SignalMatches,
425	) (matched bool, confidence float64, matchedRules []string) {
426		bestConf := 0.0
427		var bestRules []string
428		for _, child := range children {
429			m, c, r := e.evalNode(child, signals)
430			if m && (!matched || c > bestConf) {
431				matched = true
432				bestConf = c
433				bestRules = r
434			}
435		}
436		if matched {
437			return true, bestConf, bestRules
438		}
439		return false, 0, nil
440	}
441	
442	// evalNOT is a strictly unary operator: it negates the result of its single child.
443	// Configuration errors (0 or 2+ children) are treated as non-matching.
444	func (e *DecisionEngine) evalNOT(
445		children []config.RuleNode,
446		signals *SignalMatches,
447	) (matched bool, confidence float64, matchedRules []string) {
448		if len(children) != 1 {
449			logging.Warnf("NOT operator requires exactly 1 child, got %d — treating as non-match", len(children))
450			return false, 0, nil
451		}
452		m, c, r := e.evalNode(children[0], signals)
453		if !m {
454			// Child did not match → NOT matches with full certainty.
455			return true, 1.0, r
456		}
457		// Child matched → NOT does not match.
458		return false, c, r
459	}
460	
461	// matchesDomainCondition checks if any of the detected domains match the given category name
462	// A match occurs if:
463	// 1. The detected domain equals the category name directly, OR
464	// 2. The detected domain is in the category's mmlu_categories list
465	func (e *DecisionEngine) matchesDomainCondition(categoryName string, detectedDomains []string) bool {
466		// Direct match: detected domain equals the category name
467		if slices.Contains(detectedDomains, categoryName) {
468			return true
469		}
470	
471		// Check if any detected domain is in the category's mmlu_categories
472		for _, cat := range e.categories {
473			if cat.Name == categoryName {
474				for _, detectedDomain := range detectedDomains {
475					if slices.Contains(cat.MMLUCategories, detectedDomain) {
476						return true
477					}
478				}
479				break // Found the category, no need to continue
480			}
481		}
482		return false
483	}
484	
485	// selectBestDecision selects the best decision based on the configured strategy
486	func (e *DecisionEngine) selectBestDecision(results []DecisionResult) *DecisionResult {
487		if len(results) == 0 {
488			return nil
489		}
490	
491		if len(results) == 1 {
492			return &results[0]
493		}
494	
495		useTieredSelection := e.useTieredSelection(results)
496		sort.Slice(results, func(i, j int) bool {
497			return e.decisionResultLess(results[i], results[j], useTieredSelection)
498		})
499	
500		return &results[0]
501	}
502	
503	func (e *DecisionEngine) useTieredSelection(results []DecisionResult) bool {
504		for _, result := range results {
505			if result.Decision != nil && result.Decision.Tier > 0 {
506				return true
507			}
508		}
509		return false
510	}
511	
512	func (e *DecisionEngine) decisionResultLess(
513		left DecisionResult,
514		right DecisionResult,
515		useTieredSelection bool,
516	) bool {
517		if useTieredSelection {
518			if left.Decision.Tier != right.Decision.Tier {
519				return left.Decision.Tier < right.Decision.Tier
520			}
521			if left.Confidence != right.Confidence {
522				return left.Confidence > right.Confidence
523			}
524			if left.Decision.Priority != right.Decision.Priority {
525				return left.Decision.Priority > right.Decision.Priority
526			}
527			return left.Decision.Name < right.Decision.Name
528		}
529	
530		if e.strategy == config.RoutingStrategyConfidence {
531			if left.Confidence != right.Confidence {
532				return left.Confidence > right.Confidence
533			}
534			if left.Decision.Priority != right.Decision.Priority {
535				return left.Decision.Priority > right.Decision.Priority
536			}
537			return left.Decision.Name < right.Decision.Name
538		}
539	
540		if left.Decision.Priority != right.Decision.Priority {
541			return left.Decision.Priority > right.Decision.Priority
542		}
543		if left.Confidence != right.Confidence {
544			return left.Confidence > right.Confidence
545		}
546		return left.Decision.Name < right.Decision.Name
547	}
