8	
9	// resolveEntrypointForRequest resolves the routing profile before any signal
10	// evaluation. Auto and direct-looper aliases select the default recipe, named
11	// entrypoints select their mapped recipe, and concrete backend models keep a
12	// nil recipe so they bypass recipe routing entirely.
13	func (r *OpenAIRouter) resolveEntrypointForRequest(originalModel string, ctx *RequestContext) {
14		if r == nil || r.Config == nil || ctx == nil {
15			return
16		}
17		recipe, ok := r.Config.RecipeForRoutingModel(originalModel)
18		if !ok {
19			ctx.Routing.SelectPassthrough()
20			return
21		}
22		ctx.Routing.SelectRecipe(recipe)
23		logging.ComponentDebugEvent("extproc", "entrypoint_recipe_resolved", map[string]interface{}{
24			"request_id": ctx.RequestID,
25			"model":      originalModel,
26			"recipe":     recipe.Name,
27		})
28	}
29	
30	func (r *OpenAIRouter) classifierForRequest(ctx *RequestContext) *classification.Classifier {
31		if r == nil || ctx == nil || ctx.Routing.SelectedRecipe() == nil {
32			return nil
33		}
34		recipe := ctx.Routing.SelectedRecipe()
35		// Programmatic single-profile routers may provide only the default
36		// classifier. Named recipes never fall back across the isolation boundary.
37		if r.RecipeClassifiers == nil {
38			if recipe.Name == config.DefaultRecipeName {
39				return r.Classifier
40			}
41			return nil
42		}
43		classifier, ok := r.RecipeClassifiers.ForRecipe(recipe.Name)
44		if !ok {
45			return nil
46		}
47		return classifier
48	}
49	
50	// requestModelActsAsAuto reports whether the inbound model name is resolved by
51	// the router (auto slugs and entrypoint virtual names) rather than forwarded
52	// as a concrete backend model.
53	func (r *OpenAIRouter) requestModelActsAsAuto(modelName string) bool {
54		if r == nil || r.Config == nil {
55			return false
56		}
57		return r.Config.IsAutoModelName(modelName) || r.Config.IsEntrypointModelName(modelName)
58	}
59	
60	// decisionCandidatesForRequest scopes evaluation to exactly one recipe. Direct
61	// looper aliases additionally filter the default recipe by algorithm type.
62	func (r *OpenAIRouter) decisionCandidatesForRequest(originalModel string, ctx *RequestContext) []config.Decision {
63		if ctx != nil && ctx.Routing.SelectedRecipe() != nil {
64			recipe := ctx.Routing.SelectedRecipe()
65			if r.Config.IsReMoMModelName(originalModel) || r.Config.IsFusionModelName(originalModel) || r.Config.IsFlowModelName(originalModel) {
66				return r.decisionCandidatesForRequestModel(originalModel)
67			}
68			if recipe.Profile.Decisions == nil {
69				// A recipe with no decisions still scopes evaluation: an empty,
70				// non-nil slice keeps runDecisionEngine from falling back to the
71				// default profile's decisions.
72				return []config.Decision{}
73			}
74			return recipe.Profile.Decisions
75		}
76		return []config.Decision{}
77	}
