19	// handleRequestBodyDispatch routes body messages to the correct handler.
20	//
21	// BUFFERED mode (default): the message goes straight to handleRequestBody.
22	//
23	// STREAMED mode (streamed_body_mode: true in config): Envoy sends multiple
24	// body messages. A StreamedBodyHandler accumulates chunks, detects the model
25	// from the first few KB, and either passes through or accumulates for the
26	// full pipeline on end_of_stream.
27	func (r *OpenAIRouter) handleRequestBodyDispatch(v *ext_proc.ProcessingRequest_RequestBody, ctx *RequestContext) (*ext_proc.ProcessingResponse, error) {
28		// Honor x-vsr-skip-processing before allocating a streamed-body handler.
29		// This guarantees no chunk accumulation, model detection, or buffered
30		// pipeline runs for opted-out requests, regardless of streamed_body_mode.
31		if ctx.SkipProcessing {
32			if ctx.FullDuplexRequestBody {
33				return newFullDuplexRequestBodyResponse(v.RequestBody.GetBody(), v.RequestBody.GetEndOfStream()), nil
34			}
35			return newContinueRequestBodyResponse(), nil
36		}
37	
38		eos := v.RequestBody.GetEndOfStream()
39	
40		// If we already have a handler from a previous chunk, continue streaming
41		if ctx.StreamedBody != nil {
42			resp, err := ctx.StreamedBody.HandleChunk(v.RequestBody, ctx)
43			if eos {
44				ctx.StreamedBody.Release()
45				ctx.StreamedBody = nil
46			}
47			return resp, err
48		}
49	
50		// Decide mode based on config: only use streaming handler when explicitly enabled
51		streamedMode := r.Config != nil && r.Config.StreamedBodyMode
52		if ctx.FullDuplexRequestBody && !streamedMode {
53			return newFullDuplexRequestBodyResponse(v.RequestBody.GetBody(), eos), nil
54		}
55		if streamedMode && (!eos || ctx.FullDuplexRequestBody) {
56			ctx.StreamedBody = newStreamedBodyHandler(r, ctx)
57			resp, err := ctx.StreamedBody.HandleChunk(v.RequestBody, ctx)
58			if eos {
59				ctx.StreamedBody.Release()
60				ctx.StreamedBody = nil
61			}
62			return resp, err
63		}
64	
65		// BUFFERED mode or single-message STREAMED — use classic pipeline
66		return r.handleRequestBody(v, ctx)
67	}
