69	// Process implements the ext_proc calls
70	func (r *OpenAIRouter) Process(stream ext_proc.ExternalProcessor_ProcessServer) (retErr error) {
71		logging.Debugf("Processing at stage [init]")
72	
73		// Recover from any panic (including OOM kills surfaced as runtime panics from
74		// CGO inference calls) so a single bad request cannot take down the gRPC server.
75		defer func() {
76			if rec := recover(); rec != nil {
77				logging.Errorf("Process: recovered panic: %v\n%s", rec, debug.Stack())
78				retErr = status.Errorf(codes.Internal, "internal error: %v", rec)
79			}
80		}()
81	
82		// Initialize request context
83		ctx := &RequestContext{
84			Headers:      make(map[string]string),
85			TraceContext: stream.Context(),
86		}
87	
88		for {
89			req, err := stream.Recv()
90			if err != nil {
91				return r.handleProcessReceiveError(ctx, err)
92			}
93	
94			if err := r.handleProcessRequest(stream, req, ctx); err != nil {
95				return err
96			}
97		}
98	}
