100	func (r *OpenAIRouter) handleProcessReceiveError(ctx *RequestContext, err error) error {
101		if ctx.IsStreamingResponse && !ctx.StreamingComplete {
102			ctx.StreamingAborted = true
103			logging.Debugf("Streaming response aborted before completion, will not cache")
104		}
105		if ctx.InflightToken != 0 {
106			inflight.End(ctx.RequestModel, ctx.InflightToken)
107			ctx.InflightToken = 0
108		}
109	
110		if errors.Is(err, io.EOF) {
111			logging.Debugf("Stream ended gracefully")
112			return nil
113		}
114	
115		if handled := handleProcessStatusError(ctx, err); handled {
116			return nil
117		}
118	
119		if handled := handleProcessContextError(ctx, err); handled {
120			return nil
121		}
122	
123		logging.Errorf("Error receiving request: %v", err)
124		return err
125	}
