117	func WarmupRouter(
118		ctx context.Context,
119		warmups []RouterWarmupTask,
120		options WarmupRouterOptions,
121	) (Summary, error) {
122		component := options.Component
123		if component == "" {
124			component = "router"
125		}
126	
127		tasks := make([]Task, 0, len(warmups))
128		taskNames := make([]string, 0, len(warmups))
129		for _, warmup := range warmups {
130			if !warmup.Ready {
131				logging.ComponentEvent(component, warmup.Name+"_load_skipped", map[string]interface{}{
132					"reason": warmup.SkipReason,
133				})
134				continue
135			}
136			if warmup.Load == nil {
137				continue
138			}
139			taskName := "router.warmup." + warmup.Name
140			taskNames = append(taskNames, warmup.Name)
141			tasks = append(tasks, Task{
142				Name:       taskName,
143				BestEffort: true,
144				Run: func(context.Context) error {
145					logging.ComponentEvent(component, warmup.Name+"_load_started", map[string]interface{}{})
146					return warmup.Load()
147				},
148			})
149		}
150		if len(tasks) == 0 {
151			return Summary{Results: map[string]TaskResult{}}, nil
152		}
153	
154		logging.ComponentEvent(component, "runtime_warmup_started", map[string]interface{}{
155			"tasks": strings.Join(taskNames, ","),
156		})
157		summary, err := Execute(ctx, tasks, Options{
158			MaxParallelism: options.MaxParallelism,
159			OnEvent:        options.OnEvent,
160		})
161		if err != nil {
162			return summary, err
163		}
164		for _, warmup := range warmups {
165			result, ok := summary.Results["router.warmup."+warmup.Name]
166			if ok && result.Status == TaskSucceeded {
167				logging.ComponentEvent(component, warmup.Name+"_loaded", map[string]interface{}{})
168			}
169		}
170		return summary, nil
171	}
