592	func remoteEmbeddingProviderRuntimeStateFromConfig(cfg *config.RouterConfig) *EmbeddingProviderRuntimeState {
593		if cfg == nil || !cfg.EmbeddingModels.UsesRemoteEmbeddingBackend() {
594			return nil
595		}
596	
597		apiKeyEnv := strings.TrimSpace(cfg.EmbeddingModels.Endpoint.APIKeyEnv)
598		var apiKeyEnvSet *bool
599		if apiKeyEnv != "" {
600			value := os.Getenv(apiKeyEnv) != ""
601			apiKeyEnvSet = &value
602		}
603	
604		dimension := cfg.EmbeddingModels.Endpoint.Dimensions
605		if dimension == 0 {
606			dimension = cfg.EmbeddingModels.EmbeddingConfig.TargetDimension
607		}
608	
609		return &EmbeddingProviderRuntimeState{
610			Mode:         "remote",
611			Backend:      cfg.EmbeddingModels.EmbeddingBackend(),
612			Model:        strings.TrimSpace(cfg.EmbeddingModels.Endpoint.Model),
613			Dimension:    dimension,
614			APIKeyEnv:    apiKeyEnv,
615			APIKeyEnvSet: apiKeyEnvSet,
616		}
617	}
