674	func remoteEmbeddingRuntimeTask(
675		cfg *config.RouterConfig,
676		component string,
677		tracker *embeddingStateTracker,
678	) []Task {
679		return []Task{{
680			Name:       "router.embedding.remote_provider",
681			BestEffort: true,
682			Run: func(ctx context.Context) error {
683				logging.ComponentEvent(component, "remote_embedding_init_started", map[string]interface{}{
684					"backend": cfg.EmbeddingModels.EmbeddingBackend(),
685					"model":   cfg.EmbeddingModels.Endpoint.Model,
686				})
687				provider, err := embedding.NewProvider(cfg.EmbeddingModels, embedding.ProviderOptions{})
688				if err != nil {
689					tracker.markEmbeddingProvider(remoteEmbeddingProviderProbeStatus(cfg, nil, 0, err))
690					logging.ComponentErrorEvent(component, "remote_embedding_init_failed", map[string]interface{}{
691						"error": err.Error(),
692					})
693					return fmt.Errorf("failed to initialize remote embedding provider: %w", err)
694				}
695				embeddingVector, err := provider.Embed(ctx, "semantic router embedding probe")
696				if err != nil {
697					tracker.markEmbeddingProvider(remoteEmbeddingProviderProbeStatus(cfg, provider, 0, err))
698					logging.ComponentErrorEvent(component, "remote_embedding_init_failed", map[string]interface{}{
699						"backend": provider.Backend(),
700						"error":   err.Error(),
701					})
702					return fmt.Errorf("failed to probe remote embedding provider: %w", err)
703				}
704				tracker.markEmbeddingProvider(remoteEmbeddingProviderProbeStatus(cfg, provider, len(embeddingVector), nil))
705				logging.ComponentEvent(component, "remote_embedding_initialized", map[string]interface{}{
706					"backend":   provider.Backend(),
707					"dimension": len(embeddingVector),
708				})
709				tracker.markToolsReady()
710				return nil
711			},
712		}}
713	}
